import{_ as t,o,c as e,a5 as d}from"./chunks/framework.C588jwcu.js";const _=JSON.parse('{"title":"安裝","description":"","frontmatter":{"title":"安裝","order":1},"headers":[],"relativePath":"tc/latest/konadotnet/install_konadotnet.md","filePath":"tc/latest/konadotnet/install_konadotnet.md","lastUpdated":1785683504000}'),l={name:"tc/latest/konadotnet/install_konadotnet.md"};function n(i,a,s,r,c,h){return o(),e("div",null,[...a[0]||(a[0]=[d('<h1 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to &quot;安裝&quot;">​</a></h1><h2 id="基礎依賴" tabindex="-1">基礎依賴 <a class="header-anchor" href="#基礎依賴" aria-label="Permalink to &quot;基礎依賴&quot;">​</a></h2><ol><li>安裝 Konado 插件（必須）</li><li>支援 C# 的 Godot 版本（推薦 4.7.1 或更高版本）</li><li>專案需要使用 Godot .NET 編輯器開啟，普通 Godot 編輯器無法編譯與載入 C# 插件腳本。</li></ol><h2 id="安裝步驟" tabindex="-1">安裝步驟 <a class="header-anchor" href="#安裝步驟" aria-label="Permalink to &quot;安裝步驟&quot;">​</a></h2><ol><li>將 konadotnet 插件解壓縮到 Godot 專案的 <code>addons</code> 目錄下</li><li>確認 <code>addons/konado</code> 主插件也在專案中</li><li>在 Godot 編輯器中，進入 <code>專案 -&gt; 專案設定 -&gt; 插件</code>，先啟用 <code>Konado</code></li><li>建構 C# 專案，確保 MSBuild 沒有錯誤</li><li>再啟用 <code>Konadotnet</code> 插件</li><li>重新開啟專案，讓自動載入節點與 C# 腳本狀態刷新</li></ol><h2 id="首次啟用時的常見錯誤" tabindex="-1">首次啟用時的常見錯誤 <a class="header-anchor" href="#首次啟用時的常見錯誤" aria-label="Permalink to &quot;首次啟用時的常見錯誤&quot;">​</a></h2><p>若專案尚未完成 C# 建構，首次啟用可能出現：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Unable to load addon script from path: &#39;res://addons/konadotnet/Konadotnet.cs&#39;.</span></span></code></pre></div><p>請先使用 Godot .NET 編輯器建構專案，再重新開啟專案並啟用插件。</p><h2 id="場景要求" tabindex="-1">場景要求 <a class="header-anchor" href="#場景要求" aria-label="Permalink to &quot;場景要求&quot;">​</a></h2><p>使用 <code>DialogueManagerAPI</code> 時，場景樹中需要包含符合完整公開 API 契約的 <code>KND_DialogueManager</code> 節點。節點進入場景樹時會自動綁定，不依賴節點名稱。</p><p>若有多個對話管理器，請手動綁定。</p>',12)])])}const u=t(l,[["render",n]]);export{_ as __pageData,u as default};
